prompt --application/shared_components/logic/application_processes/whuch_usr_guide_to_disp
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(7264315604630027669)
,p_process_sequence=>1
,p_process_point=>'BEFORE_HEADER'
,p_process_name=>'Whuch_Usr_Guide_To_Disp'
,p_static_id=>'whuch-usr-guide-to-disp'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_result BOOLEAN;',
'BEGIN',
'    IF (MXSFT_PKG.is_Employee(v(''APP_USER'')) = MXSFT_PKG.cvv(''C_YES'') AND ',
'        MXSFT_PKG.is_Analyst(v(''APP_USER'')) = MXSFT_PKG.cvv(''C_YES'')) OR ',
'       (MXSFT_PKG.is_Analyst(v(''APP_USER'')) = MXSFT_PKG.cvv(''C_YES''))',
'    THEN ',
'        l_result := TRUE;',
'    ELSE',
'        l_result := FALSE;',
'    END IF;',
'',
'    -- Set the result as an Apex Application Item or Session State',
'    APEX_UTIL.SET_SESSION_STATE(''G_USR_GUIDE'', CASE WHEN l_result THEN ''TRUE'' ELSE ''FALSE'' END);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_version_scn=>'1'
,p_created_on=>wwv_flow_imp.dz('20230713121651Z')
,p_updated_on=>wwv_flow_imp.dz('20230713121755Z')
,p_created_by=>'BHUVI.CHAUHAN@ORACLE.COM'
,p_updated_by=>'BHUVI.CHAUHAN@ORACLE.COM'
);
end;
