wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(14163412657323864362)
,p_name=>'Requests'
,p_static_id=>'requests'
,p_region_name=>'REQUEST_LIST'
,p_parent_plug_id=>wwv_flow_imp.id(14163411686202864352)
,p_template=>wwv_flow_imp.id(14225074137638608544)
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#:t-Region--accent3:t-Region--noBorder:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select r.*, ',
'case when MXSFT_PKG.is_Printable(r.request_id)=MXSFT_PKG.cvv(''c_YES'') then ''inline'' else ''none'' end  Printable,',
'case when MXSFT_PKG.is_Submissible(r.request_id)=MXSFT_PKG.cvv(''c_YES'') then ''inline'' else ''none'' end  Submissible,',
'case when MXSFT_PKG.is_Revocable(r.request_id)=MXSFT_PKG.cvv(''c_YES'') then ''inline'' else ''none'' end  Revocable,',
'case when MXSFT_PKG.is_Editable(r.request_id)=MXSFT_PKG.cvv(''c_YES'') then ''inline'' else ''none'' end  Editable,',
'case when MXSFT_PKG.is_Attachable(r.request_id)=MXSFT_PKG.cvv(''c_YES'') then ''inline'' else ''none'' end  Attachable,',
'case when MXSFT_PKG.is_Commentable(r.request_id)=MXSFT_PKG.cvv(''c_YES'') then ''inline'' else ''none'' end  Commentable,',
'case ',
'when r.status_id in (MXSFT_PKG.Status(''New''),MXSFT_PKG.Status(''Returned'')) then',
'''<span class="tooltip" style="font-size:300%;color:red;animation-name:animcolor;animation-duration:2s;animation-iteration-count: infinite;"><span aria-hidden="true" class="fa fa-gear fa-5x fa-anim-flash fa-lg"></span><span class="tooltiptext">Not Sub'
||'mitted Yet</span></span>''',
'when r.status_id = MXSFT_PKG.Status(''Reported'') then ''<span aria-hidden="true" class="u-color-4 fa fa-flag-checkered fa-2x fa-lg"></span>''',
'else ''<span aria-hidden="true" class="u-color-7-text fa fa-repeat fa-2x fa-anim-spin fa-lg"></span>''',
'end signal',
'from MXSFT_Requests r',
'where employee_id=MXSFT_PKG.get_employee_id(:APP_USER)',
'and actual_sign is not null and deleted_sign is null'))
,p_display_when_condition=>'MXSFT_PKG.get_employee_id(:APP_USER) is not null'
,p_display_when_cond2=>'PLSQL'
,p_display_condition_type=>'EXPRESSION'
,p_ajax_enabled=>'Y'
,p_fixed_header=>'PAGE'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(14225084135705608559)
