,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'v_ret varchar2(4000 char);',
'begin',
'select ''inline'' into v_ret from mxsft_requests r, mxsft_employees e',
'where r.actual_sign is not null and r.deleted_sign is null',
'and e.actual_sign is not null and e.deleted_sign is null',
'and r.employee_id = e.employee_id',
'and e.sso_id=:APP_USER',
'and MXSFT_pkg.is_Editable(r.request_id) = ''Y''',
'and MXSFT_pkg.is_Printable(r.request_id) = ''N'';',
'return v_ret;',
'exception when others then return ''none'';',
'end;'))
