,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'v_fn varchar2(4000 char);',
'v_bc blob;',
'v_old_attachment_id number;',
'begin',
'select filename,blob_content into v_fn, v_bc from apex_application_temp_files where name=:P13_BROWSE;',
'',
'begin',
'',
'if lower(v_fn) not like ''%.pdf'' then raise_application_error(-20001, ''Attachment must be in PDF format only - ''||v_fn); end if;',
'  ',
'select attachment_id into v_old_attachment_id from MXSFT_attachments where actual_sign = MXSFT_pkg.cvv(''c_YES'') and nvl(deleted_sign,MXSFT_pkg.cvv(''c_NO'')) = MXSFT_pkg.cvv(''c_NO'') and request_id=:P13_REQUEST_ID ',
'and attachment_type = 0;',
'MXSFT_pkg.del_attachment(v_old_attachment_id);',
'exception when no_data_found then null;',
'end;',
'',
'MXSFT_pkg.new_attachment(:P13_REQUEST_ID,MXSFT_pkg.get_Employee_Number(to_number(:P13_EMPLOYEE_ID))||''.''||regexp_replace(v_fn,''.*\.'',''''),0,v_bc);',
'',
'exception when no_data_found then raise_application_error(-20001,''No File selected'');',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(14640091533379253909)
,p_internal_uid=>14640093674729253920
);
